% ORRERY reference scenario S4-leo-j2: LEO with J2 (EarthFixed), 1 day
% Generated by rain_atlas.orrery.gmat; run with: GmatConsole --run <this file>
SolarSystem.EphemerisSource = 'SPICE';
SolarSystem.SPKFilename = 'de421.bsp';
Earth.NutationUpdateInterval = 0;

Create Spacecraft Sat;
Sat.DateFormat = UTCGregorian;
Sat.Epoch = '15 Jan 2026 00:00:00.000';
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DisplayStateType = Cartesian;
Sat.X = 3140.426905642162;
Sat.Y = 4934.9447007026465;
Sat.Z = 3411.0614920951393;
Sat.VX = -6.099408469974278;
Sat.VY = 0.6961135686551336;
Sat.VZ = 4.608379103488943;

Create ForceModel FM;
FM.CentralBody = Earth;
FM.PrimaryBodies = {Earth};
FM.GravityField.Earth.Degree = 2;
FM.GravityField.Earth.Order = 0;
FM.GravityField.Earth.PotentialFile = 'JGM3.cof';
FM.GravityField.Earth.TideModel = 'None';
FM.PointMasses = {};
FM.Drag.AtmosphereModel = None;
FM.SRP = Off;
FM.RelativisticCorrection = Off;
FM.ErrorControl = RSSStep;

Create Propagator Prop;
Prop.FM = FM;
Prop.Type = RungeKutta89;
Prop.InitialStepSize = 60;
Prop.Accuracy = 1e-13;
Prop.MinStep = 0.001;
Prop.MaxStep = 2700;
Prop.MaxStepAttempts = 50;
Prop.StopIfAccuracyIsViolated = true;

Create ReportFile rf;
rf.Filename = 'C:/Users/chris/AppData/Local/Temp/claude/orrery-gmat/S4-leo-j2/S4-leo-j2.txt';
rf.Precision = 17;
rf.WriteHeaders = false;
rf.LeftJustify = On;
rf.ZeroFill = Off;

Create Variable I;

BeginMissionSequence;
Report rf Sat.ElapsedSecs Sat.A1ModJulian Sat.TAIModJulian Sat.TTModJulian Sat.TDBModJulian Sat.UTCModJulian Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ Sat.EarthFixed.X Sat.EarthFixed.Y Sat.EarthFixed.Z Sat.EarthFixed.VX Sat.EarthFixed.VY Sat.EarthFixed.VZ;
For I = 1:1440;
   Propagate Prop(Sat) {Sat.ElapsedSecs = 60.0};
   Report rf Sat.ElapsedSecs Sat.A1ModJulian Sat.TAIModJulian Sat.TTModJulian Sat.TDBModJulian Sat.UTCModJulian Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ Sat.EarthFixed.X Sat.EarthFixed.Y Sat.EarthFixed.Z Sat.EarthFixed.VX Sat.EarthFixed.VY Sat.EarthFixed.VZ;
EndFor;
